/**
 * Integration test setup
 * Sets up real database connections for integration tests
 */

import { jest } from '@jest/globals';
import { PrismaClient } from '@teaching-engine/database';

// Global test database instance
let testDb: PrismaClient;

// Initialize test database
beforeAll(async () => {
  // Use a dedicated test database URL
  const testDbUrl = process.env.TEST_DATABASE_URL || process.env.DATABASE_URL || 'file:./test-integration.db';
  
  testDb = new PrismaClient({
    datasources: {
      db: {
        url: testDbUrl,
      },
    },
    log: process.env.DEBUG_TESTS === 'true' ? ['query', 'error', 'warn'] : ['error'],
  });
  
  // Connect to database
  await testDb.$connect();
  
  // Clear all data for clean test environment
  if (process.env.SKIP_DB_CLEANUP !== 'true') {
    await cleanDatabase();
  }
});

// Clean up after all tests
afterAll(async () => {
  if (testDb) {
    await testDb.$disconnect();
  }
});

// Clean database between test suites
beforeEach(async () => {
  if (process.env.CLEAN_DB_BETWEEN_TESTS === 'true') {
    await cleanDatabase();
  }
});

// Helper function to clean database
async function cleanDatabase() {
  // Delete in correct order to respect foreign key constraints
  const deletions = [
    testDb.goalReflection.deleteMany(),
    testDb.studentGoal.deleteMany(),
    testDb.assessmentResult.deleteMany(),
    testDb.evidence.deleteMany(),
    testDb.milestone_alert.deleteMany(),
    testDb.notification.deleteMany(),
    testDb.note.deleteMany(),
    testDb.aISuggestedActivity.deleteMany(),
    testDb.lessonPlanActivity.deleteMany(),
    testDb.lessonPlan.deleteMany(),
    testDb.activityOutcome.deleteMany(),
    testDb.activity.deleteMany(),
    testDb.milestone.deleteMany(),
    testDb.outcomeCluster.deleteMany(),
    testDb.outcomeEmbedding.deleteMany(),
    testDb.outcome.deleteMany(),
    testDb.curriculumExpectationEmbedding.deleteMany(),
    testDb.curriculumExpectation.deleteMany(),
    testDb.curriculumImport.deleteMany(),
    testDb.dailyPlanItem.deleteMany(),
    testDb.dailyPlan.deleteMany(),
    testDb.resource.deleteMany(),
    testDb.eTFOLessonPlan.deleteMany(),
    testDb.unitPlan.deleteMany(),
    testDb.longRangePlan.deleteMany(),
    testDb.daybookEntry.deleteMany(),
    testDb.calendarEvent.deleteMany(),
    testDb.classRoutine.deleteMany(),
    testDb.teacherPreferences.deleteMany(),
    testDb.student.deleteMany(),
    testDb.subject.deleteMany(),
    testDb.user.deleteMany(),
  ];
  
  // Execute deletions in parallel where possible
  await Promise.all(deletions);
}

// Export test database instance for use in tests
export { testDb, cleanDatabase };